if (msg.statusCode === 200 || (msg.payload && msg.payload.success)) {
    node.status({ fill: 'green', shape: 'dot', text: '서버 보고 완료 ' + new Date().toLocaleTimeString() });
} else {
    // 서버 다운/네트워크면 다음 날 03:00 재시도. 서버는 26h 무보고를 알림으로 잡는다.
    node.warn('⚠️ 유지보수 보고 실패: ' + (msg.statusCode || 'no-response'));
    node.status({ fill: 'red', shape: 'ring', text: '보고 실패 ' + (msg.statusCode || '무응답') });
}
return null;
